13	// ConvertStringToInt32 converts a string to int32.
14	func ConvertStringToInt32(src string) (int32, error) {
15		parsed, err := strconv.ParseInt(src, 10, 32)
16		if err != nil {
17			return 0, err
18		}
19		return int32(parsed), nil
20	}
