8	// AppendConditions compiles the provided filters and appends the resulting SQL fragments and args.
9	func AppendConditions(ctx context.Context, engine *Engine, filters []string, dialect DialectName, where *[]string, args *[]any) error {
10		for _, filterStr := range filters {
11			stmt, err := engine.CompileToStatement(ctx, filterStr, RenderOptions{
12				Dialect:           dialect,
13				PlaceholderOffset: len(*args),
14			})
15			if err != nil {
16				return err
17			}
18			if stmt.SQL == "" {
19				continue
20			}
21			*where = append(*where, fmt.Sprintf("(%s)", stmt.SQL))
22			*args = append(*args, stmt.Args...)
23		}
24		return nil
25	}
